sys_script_include.script:
var XeroOnDemandSyncAjax = Class.create();
XeroOnDemandSyncAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    // Thin GlideAjax entry point for the on-demand sync UI Page (x_snc_spm_xero_i_0_xero_sync).
    // All rules (role it_project_manager, lock, subflow call) live in XeroIntegrationUtils.

    startSync: function() {
        var action = this.getParameter('sysparm_xero_action') + '';
        var projectSysId = (this.getParameter('sysparm_xero_project') || '') + '';
        return JSON.stringify(new XeroIntegrationUtils().startOnDemandSync(action, projectSysId));
    },

    getState: function() {
        return JSON.stringify(new XeroIntegrationUtils().getOnDemandSyncState());
    },

    getProjects: function() {
        return JSON.stringify(new XeroIntegrationUtils().getOnDemandProjects());
    },

    type: 'XeroOnDemandSyncAjax'
});
